INSERT INTO dynamo_work (run_key, pk, sk, version, status, balance, memo_state, memo)
SELECT #{runKey}, #{partition}, id::text, version, status, 0, 'VALUE', name FROM customer

  updated_at >= #{fromDate}
  AND updated_at < #{toDate}

mapper.select:
SELECT count(*) FROM (
  SELECT 1 FROM dynamo_work WHERE run_key = #{runKey}
  AND (octet_length(memo) > 407552 OR octet_length(status) NOT BETWEEN 1 AND 64 OR version < 0)
  LIMIT 1
) invalid_value

WITH targets AS (
  SELECT id, version, status FROM customer WHERE status IS DISTINCT FROM #{status}
  AND updated_at >= #{fromDate}
  AND updated_at < #{toDate}
), changed AS (
  UPDATE customer c SET status = #{status}, version = c.version + 1, updated_at = clock_timestamp()
  FROM targets t
  WHERE c.id = t.id AND c.version = t.version AND c.status IS NOT DISTINCT FROM t.status
  RETURNING c.id, c.version, c.status
), enqueued AS (
  INSERT INTO dynamo_outbox (run_key, pk, sk, version, status, memo)
  SELECT #{runKey}, #{partition}, id::text, version, status, '' FROM changed RETURNING 1
)
SELECT (SELECT count(*) FROM targets) AS expected, (SELECT count(*) FROM enqueued) AS updated

SELECT count(*) FROM (
  SELECT 1 FROM dynamo_work WHERE run_key = #{runKey}
  AND CASE WHEN sk ~ '^[1-9][0-9]{0,18}$' THEN sk::numeric > 9223372036854775807 ELSE true END
  LIMIT 1
) invalid_key
